// The case of letters in formulas follows the locale of the view: UPPER, LOWER and PROPER
// take the Turkish dotted and dotless i for the two letters they are while the view is
// Turkish, and a formula of the file that is typed again as it is shown stays what it was.
// The workbook is generated by code and kept within the first columns and rows.
import type { Page } from '@playwright/test';
import { buildXlsx, worksheetXml } from '../test/fixtures';
import { expect, test } from './helpers';

const str = (ref: string, text: string) => `<c r="${ref}" t="inlineStr"><is><t>${text}</t></is></c>`;
const formula = (ref: string, text: string, value: number) => `<c r="${ref}"><f>${text}</f><v>${value}</v></c>`;

/** A1 "izmir"; B1 calls VAL, a function the engine does not have (the file says 7) and the Turkish name of DGET. */
const workbook = () =>
  buildXlsx({
    sheets: [{ name: 'Case', xml: worksheetXml(`<sheetData><row r="1">${str('A1', 'izmir')}${formula('B1', 'VAL(A1)', 7)}</row></sheetData>`) }],
  });

async function mount(page: Page, bytes: Uint8Array, options: Record<string, unknown>): Promise<void> {
  await page.goto('/e2e/pages/editor.html');
  await page.waitForFunction(() => typeof (window as any).__mountEditor === 'function');
  await page.evaluate(
    async ({ base64, options }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountEditor(data, options, 'host');
    },
    { base64: Buffer.from(bytes).toString('base64'), options },
  );
}

const select = (page: Page, ref: string) =>
  page.evaluate((ref) => {
    const api = (window as any).BymOffice;
    const view = (window as any).__editor.view;
    view.select(api.parseRange(ref));
    view.focus();
  }, ref);

interface CellInfo {
  value: number | string | boolean | null;
  formula: string | null;
}

const cell = (page: Page, ref: string): Promise<CellInfo> =>
  page.evaluate((ref) => {
    const api = (window as any).BymOffice;
    const at = api.parseCellRef(ref);
    const found = api.getCell((window as any).__editor.view.workbook.sheets[0], at.row, at.col);
    return found ? { value: found.value, formula: found.formula ? found.formula.text : null } : { value: null, formula: null };
  }, ref);

/** Types into a cell and presses Enter. */
async function typeIn(page: Page, ref: string, text: string): Promise<void> {
  await select(page, ref);
  await page.keyboard.type(text);
  await page.keyboard.press('Enter');
}

test.describe('the case of letters follows the locale of the view', () => {
  test('UPPER, LOWER and PROPER in a Turkish view, and in English after setLocale', async ({ page }) => {
    await mount(page, await workbook(), { locale: 'tr' });
    await typeIn(page, 'A3', '=UPPER("i")');
    await expect.poll(() => cell(page, 'A3')).toEqual({ value: 'İ', formula: 'UPPER("i")' });
    await typeIn(page, 'A4', '=BÜYÜKHARF(A1)');
    await expect.poll(() => cell(page, 'A4')).toEqual({ value: 'İZMİR', formula: 'UPPER(A1)' });
    await typeIn(page, 'A5', '=KÜÇÜKHARF("IŞIK")');
    await expect.poll(() => cell(page, 'A5')).toEqual({ value: 'ışık', formula: 'LOWER("IŞIK")' });
    await typeIn(page, 'A6', '=YAZIM.DÜZENİ(A1)');
    await expect.poll(() => cell(page, 'A6')).toEqual({ value: 'İzmir', formula: 'PROPER(A1)' });

    await page.evaluate(() => (window as any).__editor.setLocale('en-US'));
    // A formula entered now is calculated the English way.
    await typeIn(page, 'B3', '=UPPER("i")');
    await expect.poll(() => cell(page, 'B3')).toEqual({ value: 'I', formula: 'UPPER("i")' });
    // What an older formula reads changes: it is calculated again, in the locale of now.
    await typeIn(page, 'A1', 'izmit');
    await expect.poll(() => cell(page, 'A4')).toEqual({ value: 'IZMIT', formula: 'UPPER(A1)' });
  });

  test('a function of the file that is called like a Turkish one stays itself when the formula is edited', async ({ page }) => {
    await mount(page, await workbook(), { locale: 'tr' });
    // Looked at and left: nothing is written.
    await select(page, 'B1');
    await page.keyboard.press('F2');
    await page.keyboard.press('Enter');
    expect(await cell(page, 'B1')).toEqual({ value: 7, formula: 'VAL(A1)' });
    // Changed: the name the formula called already is not read as DGET; what is new is read the Turkish way.
    await select(page, 'B1');
    await page.keyboard.press('F2');
    await page.keyboard.type('&KOD("a")');
    await page.keyboard.press('Enter');
    expect((await cell(page, 'B1')).formula).toBe('VAL(A1)&CODE("a")');
    // In a cell that held no such formula the name is the Turkish one.
    await typeIn(page, 'C3', '=KOD("A")');
    await expect.poll(() => cell(page, 'C3')).toEqual({ value: 65, formula: 'CODE("A")' });
  });
});
